def _inline_r_setup(code: str) -> str:
    code = code.strip()
    lines = code.splitlines()
    options = [line for line in lines if line.startswith('options()')]
    lines = [line for line in lines if not line.startswith('options()')]
    if options:
        options = re.sub(r'options\(.*\).*$', '', options, flags=re.MULTILINE)
    return '\n'.join(lines) + '\noptions({})'.format(options)

def xargs(cmd, varargs, *, color=False, target_concurrency=1, _max_length=None, **kwargs):
