def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    bases = []
    for cls in classes:
        if cls not in bases:
            bases.append(cls)
    seen = set()
    for cls in bases:
        for b in cls.__bases__:
            if b not in seen:
                seen.add(b)
                bases.append(b)
    return bases[::-1]

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []
    return [min(classes, key=lambda cls: (cls.__mro__.index(cls), id(cls)))]

