def fill(self, coord, weight=1):
    x = coord[0]
    y = coord[1]

    if x <= self.edges[0] or x >= self.edges[-1] or y <= self.edges[0] or y >= self.edges[-1]:
        return

    i = 0
    while i < len(self.edges) - 1 and x >= self.edges[i] and x < self.edges[i+1]:
        i += 1
    j = 0
    while j < len(self.edges) - 1 and y >= self.edges[j] and y < self.edges[j+1]:
        j += 1

    if i == j:
        self.values[i] += weight
    else:
        self.values[i] += weight / 2
        self.values[j] += weight / 2

