def update_last_applied_manifest_list_from_resp(last_applied_manifest, observer_schema, response):
    """Together with update_last_applied_manifest_dict_from_resp, this
    function is called recursively to update a partial `last_applied_manifest`
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial `last_applied_manifest` being
            updated
        observer_schema (list): partial `observer_schema`
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for (resp_obj, obs_element) in zip(response, observer_schema):
        if type(resp_obj) == dict:
            for (k, v) in resp_obj.items():
                if k not in last_applied_manifest:
                    last_applied_manifest[k] = v
                    if k in obs_element:
                        update_last_applied_manifest_dict_from_resp(
                            last_applied_manifest[k], obs_element[k], resp_obj[k]
                        )
        else:
            if resp_obj not in last_applied_manifest:
                last_applied_manifest.append(resp_obj)
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[resp_obj], obs_element, resp_obj
                )

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    if not response:
        raise KeyError("Key not found in the response")
    for key, value in response.items():
        if isinstance(value, dict):
            update_last_applied_manifest_dict_from_resp(last_applied_manifest.get(key, {}), observer_schema.get(key, {}), value)
        else:
            last_applied_manifest[key] = value
    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field in observer_schema.keys():
        if field not in response:
            raise KeyError(f"Field {field} not found in response")
        if field not in last_applied_manifest:
            last_applied_manifest[field] = {}
        update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], observer_schema[field], response[field])
    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for key, value in observer_schema.items():
        if isinstance(value, dict):
            last_applied_manifest[key] = last_applied_manifest.get(key, {})
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[key], value, response)
        else:
            if key not in response:
                raise KeyError(f"{key} not present in Kubernetes response")
            last_applied_manifest[key] = response[key]

    return last_applied_manifest

