def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    formatted_sql = ''
    formatted_params = {}

    if isinstance(params, Mapping):
        # The params are a mapping, so they are named parameters
        # We need to convert them to ordinal parameters
        for key, value in params.items():
            # Add the parameter to the formatted_sql
            formatted_sql += '?'
            # Add the parameter to the formatted_params dictionary
            formatted_params[key] = value
    else:
        # The params are a sequence, so they are ordinal parameters
        # We can use them directly in the formatted_sql
        for param in params:
            # Add the parameter to the formatted_sql
            formatted_sql += '?'
            # Add the parameter to the formatted_params sequence
            formatted_params.append(param)

    return formatted_sql, formatted_params

def format(self, sql, params):
    if not (isinstance(params, Mapping) or isinstance(params, Sequence)):
        raise ValueError("params must be a Mapping or a Sequence")

    if isinstance(params, Sequence) and params:
        out_params = [{i: params[i] for i in range(len(params))}]
    elif isinstance(params, Mapping) and params:
        out_params = [params]

    return sql, out_params

def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    :param sql: The SQL query.
    :type sql: :class:`str` or :class:`bytes`
    :param params: The set of in-style parameters.
    :type params: :class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`
    :return: The formatted SQL query and the set of converted out-style parameters.
    :rtype: :class:`tuple`
    """
    if isinstance(params, Mapping):
        converted_params = {}
        for key in params:
            if isinstance(key, (str, int)):
                converted_params[f"{self.out_style}{key}"] = params[key]
        return sql.format(**converted_params), converted_params
    elif isinstance(params, Sequence):
        converted_params = []
        for param in params:
            if isinstance(param, (str, int)):
                converted_params.append(f"{self.out_style}{param}")
            else:
                converted_params.append(param)
        return sql.format(*converted_params), converted_params
    else:
        raise TypeError(f"Unsupported type for parameter 'params': {type(params)}")

def formatmany(self, sql, many_params):
    params = []
    for param in many_params:
        if isinstance(param, dict):
            params.append(dict(zip(param.keys(), repeat(None))))
        else:
            params.append(repeat(None))
    return sql, params

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    # Check if path is a valid object
    if not os.path.exists(path):
        raise ObjectNotFoundError(f"No such object: '{path}'")
    elif not os.path.isdir(path):
        raise ObjectNotDirectoryError(f"'{path}' is not a directory")

    # Check if object has an OCFL version 2 descriptor
    descriptor_path = os.path.join(path, '0=ocfl-version-2')
    if not os.path.exists(descriptor_path):
        raise ObjectHasNoOCFLVersionDescriptorError(f"Object '{path}' does not contain an OCFL version 2 descriptor")
    elif not os.path.isfile(descriptor_path):
        raise ObjectHasNoOCFLVersionDescriptorError(f"'0=ocfl-version-2' in object '{path}' is not a file")

    # Check if object has a valid ocfl-layout extension
    if not any(os.path.exists(f"{descriptor_path}.ocfl-layout_{extension}") for extension in VALID_OCFL_LAYOUT_EXENSIONS):
        raise ObjectHasInvalidOCFLLayoutExtensionError(f"Object '{path}' has no valid ocfl-layout extension")

    # Check if object has a valid root resource
    root_resource_path = os.path.join(path, 'v', '{{version}}', 'root-resource. extent="0"')
    if not os.path.exists(root_resource_path):
        raise ObjectHasNoRootResourceError(f"Object '{path}' does not contain a root resource")
    elif not os.path.isfile(root_resource_path):
        raise ObjectHasNoRootResourceError(f"'root-resource. extent=0' in object '{path}' is not a file")

    # Check if object has a valid signature
    signature_path = os.path.join(path, 'v', '{{version}}', 'signature')

