    validation_result = ValidationResult()
    version = None

    # Validate inventory in terms of schema if specified
    if schema := spec.get("schema"):
        if not isinstance(inventory, dict):
            validation_result.add_warning(f"Inventory is not a dictionary")
            return validation_result

        # Get type value from inventory if extract_spec_version is True
        if extract_spec_version:
            type_value = inventory.get("type")

            # Validate type value
            if not isinstance(type_value, str):
                validation_result.add_warning(f"Type value is not a string")
                return validation_result

            # Determine specification version based on type value
            version = type_value

        # Validate inventory against schema
        for key, value in inventory.items():
            if schema_key := schema.get(key):
                if not isinstance(value, schema_key):
                    validation_result.add_error(f"Value for key {key} is not of type {schema_key}")
            else:
                validation_result.add_warning(f"Key {key} is not present in schema")

    # Validate inventory based on older specification
    else:
        if not isinstance(inventory, list):
            validation_result.add_warning(f"Inventory is not a list")
            return validation_result

        # Set specification version to default if version not provided
        if not version:
            version = self.spec_version

        # Validate inventory items based on specification version
        for item in inventory:
            validation_result.append(inventory.validate(version))

