def extract_number_and_supplement_from_issue_element(issue):
    """
    Extracts the number and supplement from an issue element.

    :param issue: the contents of the issue element.
    :returns: a tuple containing the number and supplement, if found.
    """
    supplement_match = re.search(r"supp?(l|le)?\s*\.?\s*(\d+)", issue, re.I)
    number_match = re.search(r"\d+", issue)
    if supplement_match and number_match:
        number = int(number_match.group())
        supplement = int(supplement_match.group())
        return (number, supplement)
    elif number_match:
        return (int(number_match.group()), None)
    else:
        return (None, None)

