def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if "&" in arg and "|" in arg:
            parts = arg.split("&")
            new_parts = []
            for part in parts:
                if "|" in part:
                    new_parts.append(part.split("|")[0])
                else:
                    new_parts.append(part)
            new_args.append(" & ".join(new_parts))
        elif "|" in arg and "&" in arg:
            parts = arg.split("|")
            new_parts = []
            for part in parts:
                if "&" in part:
                    new_parts.append(part.split("&")[0])
                else:
                    new_parts.append(part)
            new_args.append(" | ".join(new_parts))
        else:
            new_args.append(arg)
    return new_args

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for arg in args:
        if arg in self.variables:
            var = self.variables[arg]
            if var.name in result:
                result.remove(var.name)
            if not var.positive:
                if var.name in self.variables:
                    other_var = self.variables[var.name]
                    if other_var.positive:
                        continue
                result.append(var.name)
        else:
            if arg not in result:
                result.append(arg)
    return result

