            result.append(And(expr.left, expr.right.operand))
        elif isinstance(expr, And) and expr.right == Not(expr.left):
            result.append(And(expr.left.operand, expr.right))
        elif isinstance(expr, Or) and expr.left == Not(expr.right):
            result.append(Or(expr.left, expr.right.operand))
        elif isinstance(expr, Or) and expr.right == Not(expr.left):
            result.append(Or(expr.left.operand, expr.right))
        else:
            result.append(expr)
    return result

