def _fromutc(self, dt):
    """
    Given a timezone-aware datetime in a given timezone, calculates a
    timezone-aware datetime in a new timezone.

    Since this is the one time that we *know* we have an unambiguous
    datetime object, we take this opportunity to determine whether the
    datetime is ambiguous and in a "fold" state (e.g. if it's the first
    occurrence, chronologically, of the ambiguous datetime).

    :param dt:
        A timezone-aware :class:`datetime.datetime` object.
    """
    if isinstance(dt, datetime.datetime):
        if dt.tzinfo is not None:
            if dt.tzinfo.utcoffset(dt) is not None:
                if len(dt.tzinfo.utcoffset(dt)) == 3:
                    return dt
                else:
                    ambig_first = dt.tzinfo._utcoffset_fold
                    if ambig_first:
                        if dt.tzinfo._utcoffset is not None:
                            return datetime.datetime(dt.year, dt.month, dt.day, dt.hour, dt.minute, dt.second, dt.microsecond, amig_first, dt.tzinfo)
                        else:
                            return datetime.datetime(dt.year, dt.month, dt.day, dt.hour, dt.minute, dt.second, dt.microsecond, fallback=dt.tzinfo_fallback, is_ambiguout=True, is_dst=True)
                    else:
                        if dt.tzinfo._utcoffset is not None:
                            return datetime.datetime(dt.year, dt.month, dt.day, dt.hour, dt.minute, dt.second, dt.microsecond, dt.tzinfo)
                        else:
