    if not commands:
        raise ValueError("command not available")

    if type(commands) is list:
        for command in commands:
            if command not in ("execute", "kill"):
                raise ValueError("Unsupported command")

        command_obj = {"execute": cmd_execute, "kill": cmd_kill}

