    if version.startswith("v"):
        version = version[1:]

    parts = version.split(".")
    major, minor = int(parts[0]), int(parts[1])

    if minor == 9:
        major += 1
        minor = 0
    else:
        minor += 1

    return "v" + str(major) + "." + str(minor)

