        for existing_node in result:
            existing_key, existing_value = existing_node
            if key.value == existing_key.value:
                if isinstance(existing_value, nodes.MappingNode) and isinstance(value, nodes.MappingNode):
                    existing_value.value.extend(value.value)
                elif isinstance(existing_value, nodes.MappingNode) and isinstance(value, nodes.SymbolNode):
                    existing_value.value.append(value)
