def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_arguments = {name: parser.parse_known_args(unparsed_arguments)
                        for name, parser in subparsers.items()}
    remaining_arguments = []
    for argument in unparsed_arguments:
        found_parser = None
        for name, parser in subparsers.items():
            if parser.is_known_argument(argument):
                found_parser = parser
                break
        if found_parser is not None:
            name = found_parser.name
            parsed_arguments[name] = found_parser.parse_known_args(unparsed_arguments)
            remaining_arguments = unparsed_arguments[1:]
        else:
            remaining_arguments.append(argument)
    return parsed_arguments, remaining_arguments

