        return None
    parts = frequency.split()
    if len(parts) != 2:
        raise ValueError("Invalid frequency: '%s'" % frequency)
    amount = int(parts[0])
    unit = parts[1]
    # Convert milliseconds to seconds when unit is "ms"
    if unit == "ms":
        amount /= 1000.0
    # Return a timedelta object with the appropriate unit
    return datetime.timedelta(**{unit: amount})

