def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        # If 'host' is already an IP address, convert it to a string
        if type(host) == socket.inet_address:
            host = str(host)
        result = socket.getaddrinfo(host, 0, socket.AF_INET)
    except socket.gaierror as exc:
        # Unable to resolve host
        return False
    return bool(result)

