def find_roots(graph, prop):
    todo = set(graph.nodes)
    done = set()
    roots = set()

    while todo:
        node = todo.pop()
        if node not in done:
            parents = graph.get_parents(node, prop)
            if not parents:
                # node is a root
                roots.add(node)
                done.add(node)

            for parent in parents:
                if parent not in done:
                    todo.add(parent)
    return roots

