    scheme, netloc, path, query, fragment = urlparse.urlsplit(url)
    if not scheme in ('http', 'https', 'ftp', 'ftps'):
        return None
    req = Urllib2HeadRequest(url, headers={'Host': netloc})
    resp = urlopen(req)
    try:
        if hasattr(resp, 'code') and resp.code != 200 and scheme not in ('ftp', 'ftps'):
            return None
        return resp.info().get('content-type', None)
    finally:
        resp.close()

def fetch_content_type(url: str) -> Optional[str]:
    import urllib.request
    from urllib.parse import urlparse

    scheme, netloc, path, query, fragment = urlparse.urlsplit(url)
    if scheme not in ('http', 'https', 'ftp', 'ftps'):
        return None
    req = urllib.request.Request(url, headers={'Host': netloc})
    resp = urllib.request.urlopen(req)
    try:
        if resp.code != 200 and scheme not in ('ftp', 'ftps'):
            return None
        return resp.headers.get('content-type', '')
    finally:
        resp.close()

