def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    # 1. Check if the input is a string
    if not isinstance(tag, str):
        raise TypeError("'tag' expects a string")
    # 2. Check if the input has at least one alphabetic character
    for c in tag:
        if c.isalpha():
            break
    else:
        return False
    # 3. Check if the input only contains alphabetic characters and spaces
    for c in tag:
        if not (c.isalpha() or c.isspace()):
            return False
    # 4. Check if the input is not an empty string or only contains spaces
    if tag.strip() == "":
        return False
    # 5. Check if the input is not a reserved keyword
    if tag in Reserved:
        return False
    # 6. Check if the input is not a stopword
    if tag in Stopwords:
        return False
    # 7. Check if the input is not a common suffix
    for suf in Suffixes:
        if tag.endswith(suf):
            return True
    # 8. If the input passes all the above checks, it is a valid tag
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    return {child.tag: child for child in node}

def xml_children_as_dict(node):
    children = {}
    for child in node.getchildren():
        child_tag = child.tag
        if child_tag not in children:
            children[child_tag] = child
        else:
            if not isinstance(children[child_tag], list):
                children[child_tag] = [children[child_tag], child]
            else:
                children[child_tag].append(child)
    return children

def xml_children_as_dict(node):
    if not node.childNodes:
        return None
    result = {}
    for child in node.childNodes:
        if child.nodeType != Node.ELEMENT_NODE:
            continue
        result[child.tagName] = child
    return result

