def fetch_nodeinfo_document(url, document_path=None):
    """Fetch a NodeInfo 0.1 document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if document_path is None:
        document_path = "/.well-known/nodeinfo"
    response = requests.get(url + document_path)
    if response.status_code == 200:
        return response.json()
    else:
        raise ValueError("Failed to fetch NodeInfo document: " + response.status_code)

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """

    if not url:
        raise ValueError("Missing URL argument to generate NodeInfo .well-known document")

    if not document_path:
        document_path = ".well-known/"

    if not document_path.endswith("/"):
        document_path += "/"

    if "http" not in url:
        url = "http://" + url

    if not url.startswith("http"):
        raise ValueError("Invalid URL provided to generate NodeInfo .well-known document. Must be a full URL, including protocol (http/https)")

    try:
        document, code, exception = fetch_document(url=url, path=document_path)
    except Exception as e:
        raise ValueError("Unable to fetch NodeInfo .well-known document. %s" % e)

    if code != 200:
        raise ValueError("Invalid URL or document path provided to generate NodeInfo .well-known document. %s" % code)

    if not document:
        return None

    try:
        nodeinfo_document = parse_nodeinfo_document(document)
    except Exception as e:
        raise ValueError("Unable to parse NodeInfo .well-known document. %s" % e)

    return nodeinfo_document

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """

    # Initialize the base NodeInfo document
    document = {
        "nodeinfo": {"version": "1.1", "info": {}}
    }

    # Add the elementary information if not specified
    if document_path is None:
        document["nodeinfo"]["info"]["url"] = url
    else:
        document["nodeinfo"]["info"]["url"] = f"{url}:{document_path}"

    # Handle the well-known document
    try:
        document["nodeinfo"]["well_known"] = {"url": f"{url}/.well-known/nodeinfo.json"}
    except AttributeError:
        pass

    return document

def parse_diaspora_webfinger(document: str) -> dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import xml.etree.ElementTree as ET
    import json

    # Check if document is in XRD format
    if "<XRD" in document:
        namespace = {
            "xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0",
            "openid": "http://openid.net/xmlns/1.0",
            "v": "http://rpxnow.com/v/1.0",
            "age": "http://web.resource.org/cc/",
            "cc": "http://web.resource.org/cc/",
        }
        try:
            root = ET.fromstring(document)
            arr = []
            for person in root.findall(".//v:Person", namespace):
                new_obj = {
                    "handle": person.find("./v:url").text,
                    "names": [person.findtext("./v:fn")],
                }
                arr.append(new_obj)
            return json.dumps(arr)
        except:
            pass

    # Check if document is in JSON format
    try:
        return json.loads(document)
    except:
        pass

    # Document is neither in XRD nor in JSON format
    return None

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html

    :arg document: The Diaspora webfinger document to parse
    :return: A dict containing the parsed Diaspora webfinger document
    """
    if document.startswith('{'):
        return json.loads(document)
    else:
        xrd_ns = "http://docs.oasis-open.org/ns/xri/xrd-1.0"
        xrd_nsmap = {
            "xrd": xrd_ns,
            "q": xrd_ns + "{0}"
        }
        return etree.XML(document).find("xrd\\:XRD", xrd_nsmap)

